-- DATOS — HC 6-26.xlsx + GYP.xlsx (periodo 2026-06)
-- Ejecutar DESPUÉS de supabase_schema.sql, o usar el archivo combinado.
-- =====================================================================
set search_path = olo, public;

-- 1. Periodo -----------------------------------------------------------
values (2026, 6, 'HC 6-26.xlsx', 'GYP.xlsx', 6, 472.0300,
        'Carga inicial. P&L en USD acumulado del año, dividido entre 6 meses.')
on conflict (anio, mes) do update
  set archivo_hc = excluded.archivo_hc, archivo_pl = excluded.archivo_pl,
      meses_acum = excluded.meses_acum, tipo_cambio = excluded.tipo_cambio, notas = excluded.notas;

-- Limpieza de datos previos del mismo periodo (idempotencia)
delete from empleado where periodo_id = (select id from periodo where anio=2026 and mes=6);
delete from pl_linea where periodo_id = (select id from periodo where anio=2026 and mes=6);
delete from distribucion_run where periodo_id = (select id from periodo where anio=2026 and mes=6);

-- 2. Empleados (159 registros) ----------------------------------

-- 3. Asignación empleado <-> zona (717 registros) ------------------
