-- 7. Verificación -------------------------------------------------------
-- Totales esperados: HC 159 empleados · CRC 116,286,932 · USD/mes 334,448.64
select 'empleados' as chk, count(*)::text as valor from empleado
union all select 'asignaciones', count(*)::text from empleado_zona
union all select 'lineas p&l', count(*)::text from pl_linea
union all select 'total crc', to_char(sum(costo_total_crc), 'FM999,999,999.00') from distribucion_zona
union all select 'total usd/mes', to_char(sum(costo_usd_mes), 'FM999,999,999.00') from distribucion_zona;
